        a_exc_out <= 64'sd0;
        i_exc_reg <= 64'sd0;
        i_exc_out <= 64'sd0;
        a_inh_reg <= 64'sd0;
        a_inh_out <= 64'sd0;
        i_inh_reg <= 64'sd0;
        i_inh_out <= 64'sd0;
        v_reg <= 64'sd0;
        v_out <= 64'sd0;
        spike_out <= 1'b0;
    end else begin
        if ((v_next >= P_V_THRESHOLD)) begin
            spike_out <= 1'b1;
            a_exc_reg <= a_exc_next;
            a_exc_out <= a_exc_next;
            i_exc_reg <= i_exc_next;
            i_exc_out <= i_exc_next;
            a_inh_reg <= a_inh_next;
            a_inh_out <= a_inh_next;
            i_inh_reg <= i_inh_next;
            i_inh_out <= i_inh_next;
            v_reg <= P_V_REST;
            v_out <= P_V_REST;
        end else begin
            spike_out <= 1'b0;
            a_exc_reg <= a_exc_next;
            a_exc_out <= a_exc_next;
            i_exc_reg <= i_exc_next;
            i_exc_out <= i_exc_next;
            a_inh_reg <= a_inh_next;
            a_inh_out <= a_inh_next;
            i_inh_reg <= i_inh_next;
            i_inh_out <= i_inh_next;
            v_reg <= v_next;
            v_out <= v_next;
        end
    end
end

endmodule
